#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>

using namespace std;

char mazeA[12][12], mazeB[12][12];
int dimension, maxTime;
bool visitedStates[70][12][12][12][12];
bool canReachState[12][12][12][12];
int timeMap[12][12];

void exploreStates(int step, int x, int y, int originX, int originY) {
    if (maxTime >= 70 || x < 0 || x >= dimension || y < 0 || y >= dimension)
        return;
    if (mazeA[x][y] < '0' || mazeA[x][y] > '9')
        return;
    if (step > maxTime + 1)
        return;
    if (visitedStates[step][x][y][originX][originY])
        return;
    if (timeMap[x][y] != 0 && step > timeMap[x][y])
        return;
    if (timeMap[x][y] == step && (mazeB[x][y] > '9' || mazeB[x][y] <= '0'))
        return;
    visitedStates[step][x][y][originX][originY] = true;

    if (step < timeMap[x][y]) {
        exploreStates(step + 1, x, y, originX, originY);
        exploreStates(step + 1, x + 1, y, originX, originY);
        exploreStates(step + 1, x - 1, y, originX, originY);
        exploreStates(step + 1, x, y + 1, originX, originY);
        exploreStates(step + 1, x, y - 1, originX, originY);
    }
}

int main() {
    int n, t;
    cin >> n >> t;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> mazeA[i][j];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            cin >> mazeB[i][j];

    vector<vector<int>> graph;
    vector<int> E(210, 0), H(210, 0);
    int C[210][210] = {0};
    int pN[11][11] = {0};

    queue<pair<int, int>> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            timeMap[i][j] = -1;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (mazeA[i][j] == 'Z') {
                timeMap[i][j] = 0;
                q.push({i, j});
            }

    int di[] = {-1, 0, 1, 0};
    int dj[] = {0, -1, 0, 1};

    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (timeMap[p.first][p.second] >= t) continue;
        for (int d = 0; d < 4; d++) {
            int ni = p.first + di[d], nj = p.second + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n && mazeA[ni][nj] >= '0' && mazeA[ni][nj] <= '9' && timeMap[ni][nj] == -1) {
                timeMap[ni][nj] = timeMap[p.first][p.second] + 1;
                q.push({ni, nj});
            }
        }
    }

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (timeMap[i][j] == -1)
                timeMap[i][j] = t;

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (mazeA[i][j] >= '0' && mazeA[i][j] <= '9')
                exploreStates(0, i, j, i, j);

    vector<int> startNodes;
    graph.push_back(startNodes);

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            for (int i2 = 0; i2 < n; i2++)
                for (int j2 = 0; j2 < n; j2++)
                    for (int nt = 0; nt <= t; nt++)
                        canReachState[i1][j1][i2][j2] |= visitedStates[nt][i1][j1][i2][j2];

    for (int i1 = 0; i1 < n; i1++)
        for (int j1 = 0; j1 < n; j1++)
            if (mazeA[i1][j1] > '0' && mazeA[i1][j1] <= '9') {
                int k = graph.size();
                vector<int> g;
                graph.push_back(g);
                E[k] = mazeA[i1][j1] - '0';

                for (int i2 = 0; i2 < n; i2++)
                    for (int j2 = 0; j2 < n; j2++)
                        if (mazeB[i2][j2] > '0' && mazeB[i2][j2] <= '9')
                            if (canReachState[i2][j2][i1][j1]) {
                                int _k;
                                if (pN[i2][j2] == 0) {
                                    vector<int> _g;
                                    _k = graph.size();
                                    graph.push_back(_g);
                                    pN[i2][j2] = _k;
                                } else {
                                    _k = pN[i2][j2];
                                }
                                graph[k].push_back(_k);
                                graph[_k].push_back(k);
                                C[k][_k] = 10000;
                                C[_k][k] = 0;
                            }
            }

    for (int i2 = 0; i2 < n; i2++)
        for (int j2 = 0; j2 < n; j2++)
            if (mazeB[i2][j2] > '0' && mazeB[i2][j2] <= '9' && pN[i2][j2] > 0) {
                int _k = pN[i2][j2];
                graph[_k].push_back(0);
                C[_k][0] = mazeB[i2][j2] - '0';
                C[0][_k] = 0;
            }

    while (true) {
        bool allDone = true;
        for (int i = 1; i < (int)graph.size(); i++) {
            while (E[i] > 0) {
                bool progressFlag = true;
                int minH = 10000;
                for (int neighbor : graph[i]) {
                    if (C[i][neighbor] - E[i] > 0 && H[i] == H[neighbor] + 1) {
                        int delta = min(C[i][neighbor] - E[i], E[i]);
                        F[i][neighbor] += delta;
                        F[neighbor][i] -= delta;
                        E[i] -= delta;
                        E[neighbor] += delta;
                        progressFlag = false;
                        allDone = false;
                        if (E[i] == 0) break;
                    }
                    minH = min(minH, H[neighbor]);
                }
                if (H[i] != minH + 1 && minH != 10000)
                    H[i] = minH + 1;
                if (progressFlag) break;
            }
        }
        if (allDone) break;
    }

    cout << E[0] << endl;
    return 0;
}
